			'import * as React from "react";\nimport { DownloadIcon, FileTextIcon } from "lucide-react";\nimport {\n\tAttachment,\n\tAttachmentAction,\n\tAttachmentActions,\n\tAttachmentContent,\n\tAttachmentDescription,\n\tAttachmentMedia,\n\tAttachmentTitle,\n} from "@workspace/ui/components/attachment";\n\n// Icon names are hoisted static literals because the shadcn CLI rewrites them\n// to whichever icon library the installer picked, and it can only rewrite a\n// literal. A computed or spread prop value installs as a blank square.\nconst ICON_REPORT = <FileTextIcon aria-hidden="true" />;\n\nconst ICON_DOWNLOAD = <DownloadIcon aria-hidden="true" />;\n\nexport function Attachment1Example(): React.JSX.Element {\n\treturn (\n\t\t<div className="mx-auto flex w-full max-w-sm flex-col gap-3">\n\t\t\t<p className="text-sm">Here is the cohort breakdown you asked for. Numbers run through 30 September.</p>\n\t\t\t{/*\n\t\t\t * The root sizes to its own content, so a chip meant to fill the reply\n\t\t\t * column has to be told to stretch.\n\t\t\t */}\n\t\t\t<Attachment className="w-full">\n\t\t\t\t<AttachmentMedia>{ICON_REPORT}</AttachmentMedia>\n\t\t\t\t<AttachmentContent>\n\t\t\t\t\t<AttachmentTitle>retention-cohorts-q3.pdf</AttachmentTitle>\n\t\t\t\t\t<AttachmentDescription>\n\t\t\t\t\t\tPDF\n\t\t\t\t\t\t<span aria-hidden="true" className="mx-1.5 inline-block size-1 rounded-full bg-muted-foreground/40 align-middle" />\n\t\t\t\t\t\t1.9 MB\n\t\t\t\t\t</AttachmentDescription>\n\t\t\t\t</AttachmentContent>\n\t\t\t\t<AttachmentActions>\n\t\t\t\t\t{/*\n\t\t\t\t\t * type="button" is spelled out because a bare <button> inside a form\n\t\t\t\t\t * defaults to submit, and this chip is meant to be pasted into one.\n\t\t\t\t\t */}\n\t\t\t\t\t<AttachmentAction type="button" size="icon-sm" variant="secondary" aria-label="Download retention-cohorts-q3.pdf">\n\t\t\t\t\t\t{ICON_DOWNLOAD}\n\t\t\t\t\t</AttachmentAction>\n\t\t\t\t</AttachmentActions>\n\t\t\t</Attachment>\n\t\t</div>\n\t);\n}\n',
